import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triplet_margin_loss_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void triplet_margin_loss_kernel(
    const float* anchor, 
    const float* positive, 
    const float* negative, 
    float* losses, 
    float margin, 
    int feature_size) 
{
    extern __shared__ float shared_sums[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    int offset = batch_idx * feature_size;

    const float* a = anchor + offset;
    const float* p = positive + offset;
    const float* n = negative + offset;

    float a_p_sum = 0.0f;
    float a_n_sum = 0.0f;

    int stride = blockDim.x;
    for (int i = tid; i < feature_size; i += stride) {
        float diff_ap = a[i] - p[i];
        a_p_sum += diff_ap * diff_ap;
        float diff_an = a[i] - n[i];
        a_n_sum += diff_an * diff_an;
    }

    shared_sums[tid] = a_p_sum;
    shared_sums[blockDim.x + tid] = a_n_sum;

    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sums[tid] += shared_sums[tid + s];
            shared_sums[blockDim.x + tid] += shared_sums[blockDim.x + tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float d_ap = sqrtf(shared_sums[0]);
        float d_an = sqrtf(shared_sums[blockDim.x]);
        losses[batch_idx] = fmaxf(d_ap - d_an + margin, 0.0f);
    }
}

torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor, 
    torch::Tensor positive, 
    torch::Tensor negative, 
    float margin) 
{
    TORCH_CHECK(anchor.dim() == 2, "anchor must be 2D");
    TORCH_CHECK(positive.size(0) == anchor.size(0), "batch size mismatch");
    TORCH_CHECK(negative.size(0) == anchor.size(0), "batch size mismatch");

    int batch_size = anchor.size(0);
    int feature_size = anchor.size(1);

    auto losses = torch::zeros({batch_size}, anchor.options());

    const int threads_per_block = 256;
    const int shared_mem_size = 2 * threads_per_block * sizeof(float);

    triplet_margin_loss_kernel<<<batch_size, threads_per_block, shared_mem_size>>>(
        anchor.data_ptr<float>(),
        positive.data_ptr<float>(),
        negative.data_ptr<float>(),
        losses.data_ptr<float>(),
        margin,
        feature_size
    );

    return torch::mean(losses);
}
"""

triplet_margin_loss_cpp_source = """
torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, float margin);
"""

triplet_margin_loss = load_inline(
    name='triplet_margin_loss',
    cpp_sources=triplet_margin_loss_cpp_source,
    cuda_sources=triplet_margin_loss_source,
    functions=['triplet_margin_loss_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = margin

    def forward(self, anchor, positive, negative):
        return triplet_margin_loss.triplet_margin_loss_cuda(
            anchor.contiguous(), 
            positive.contiguous(), 
            negative.contiguous(), 
            self.margin
        )
